import * as THREE from 'three'
import { useEffect, useMemo, useRef, useState } from 'react'
import { Canvas, useFrame, useThree } from '@react-three/fiber'

/**
 * AAGAMISEQ scroll hero — all Three.js via React Three Fiber.
 * Hero = one sphere. Field = many floating spheres + hover. Horizontal nanopore sheet.
 */

const heroTarget = new THREE.Vector3()
const cameraTarget = new THREE.Vector3()
const lookAtTarget = new THREE.Vector3()
const poreScale = new THREE.Vector3(1, 1, 1)
const _color = new THREE.Color()
const _hoverColor = new THREE.Color('#e8fff8')
const _objScale = new THREE.Vector3()
const _matrix = new THREE.Matrix4()
const _pos = new THREE.Vector3()
const _quat = new THREE.Quaternion()
const _scl = new THREE.Vector3()

const PALETTE = ['#7ec8c8', '#5fdad1', '#6eb4d8', '#9ad0c8', '#b8d66a', '#4eb8c0', '#8ee0d8']

const clamp = (v, min = 0, max = 1) => Math.min(Math.max(v, min), max)
const smooth = (start, end, value) => {
  const n = clamp((value - start) / (end - start))
  return n * n * (3 - 2 * n)
}
const lerp = THREE.MathUtils.lerp

const BEATS = {
  focusStart: 0.06,
  focusEnd: 0.3,
  poreInStart: 0.26,
  poreInEnd: 0.38,
  transitStart: 0.38,
  transitEnd: 0.66,
  clearStart: 0.52,
  clearEnd: 0.7,
  poreOutStart: 0.66,
  poreOutEnd: 0.78,
  brandStart: 0.76,
  brandEnd: 0.9,
}

function seededRandom(seed) {
  const x = Math.sin(seed * 127.1 + 311.7) * 43758.5453
  return x - Math.floor(x)
}

export default function App() {
  const [progress, setProgress] = useState(0)
  const targetProgress = useRef(0)

  useEffect(() => {
    const update = () => {
      const scrollable = document.documentElement.scrollHeight - window.innerHeight
      targetProgress.current = scrollable > 0 ? clamp(window.scrollY / scrollable) : 0
    }
    update()
    window.addEventListener('scroll', update, { passive: true })
    window.addEventListener('resize', update)

    let raf = 0
    const tick = () => {
      // Smooth scroll progress so motion feels polished
      setProgress((prev) => {
        const next = lerp(prev, targetProgress.current, 0.085)
        return Math.abs(next - targetProgress.current) < 0.00015 ? targetProgress.current : next
      })
      raf = requestAnimationFrame(tick)
    }
    raf = requestAnimationFrame(tick)

    return () => {
      window.removeEventListener('scroll', update)
      window.removeEventListener('resize', update)
      cancelAnimationFrame(raf)
    }
  }, [])

  const brandOpacity = smooth(BEATS.brandStart, BEATS.brandEnd, progress)
  const hintOpacity = 1 - smooth(0.02, 0.1, progress)

  return (
    <main className="experience-shell">
      <div className="gradient-orb gradient-orb-a" aria-hidden />
      <div className="gradient-orb gradient-orb-b" aria-hidden />
      <div className="gradient-orb gradient-orb-c" aria-hidden />

      <div className="canvas-stage">
        <Canvas
          dpr={[1, 1.75]}
          camera={{ position: [0, 1.2, 11], fov: 38, near: 0.1, far: 80 }}
          gl={{ antialias: true, alpha: true, powerPreference: 'high-performance' }}
          onCreated={({ gl }) => {
            gl.setClearColor(0x000000, 0)
            gl.toneMapping = THREE.ACESFilmicToneMapping
            gl.toneMappingExposure = 1.15
          }}>
          <fog attach="fog" args={['#0a4550', 16, 38]} />
          <ambientLight intensity={0.7} color="#c8fff5" />
          <directionalLight position={[6, 10, 5]} intensity={1.8} color="#ffffff" />
          <directionalLight position={[-5, 2, -3]} intensity={0.7} color="#5ec8d8" />
          <pointLight position={[0, 3, 4]} intensity={1.1} color="#9ff0e0" distance={30} />
          <pointLight position={[-4, 1, 2]} intensity={0.55} color="#74b9ff" distance={24} />

          <CameraRig progress={progress} />
          <AmbientSpheres progress={progress} />
          <InteractiveField progress={progress} />
          <HeroSphere progress={progress} />
          <Nanopore progress={progress} />
        </Canvas>

        <div className="scroll-hint" style={{ opacity: hintOpacity }}>
          Scroll to follow the molecule
        </div>

        <div className="brand-reveal" style={{ opacity: brandOpacity }}>
          <div className="brand-name">
            AAGAMI
            <span>
              SE
              <span className="brand-q">
                Q
                <i className="brand-q-dot" aria-hidden />
              </span>
            </span>
          </div>
          <p className="brand-tagline">Clarity in the fight against cancer</p>
        </div>
      </div>
      <div className="scroll-space" aria-hidden />
    </main>
  )
}

function CameraRig({ progress }) {
  const { camera } = useThree()

  useFrame((_, delta) => {
    const focus = smooth(BEATS.focusStart, BEATS.focusEnd, progress)
    const transit = smooth(BEATS.transitStart, BEATS.transitEnd, progress)
    const brand = smooth(BEATS.brandStart, BEATS.brandEnd, progress)

    const camY = lerp(1.1, 2.6, transit) * (1 - brand * 0.8) + lerp(0.35, 0.15, brand)
    const camZ = lerp(11.5, 8.4, focus)
    const throughZ = lerp(camZ, 7.6, transit)
    const finalZ = lerp(throughZ, 6.5, brand)

    cameraTarget.set(lerp(0.4, 0, focus) * (1 - brand), camY, finalZ)
    lookAtTarget.set(0, lerp(1.0, -0.35, transit) * (1 - brand * 0.65), 0)

    const ease = 1 - Math.exp(-delta * 3.8)
    camera.position.lerp(cameraTarget, ease)
    camera.lookAt(lookAtTarget)
    camera.fov = lerp(38, 31, focus)
    camera.updateProjectionMatrix()
  })

  return null
}

/** Dense background cloud — instanced spheres (no hover, performance) */
function AmbientSpheres({ progress }) {
  const mesh = useRef()
  const count = 180
  const clear = smooth(BEATS.clearStart, BEATS.clearEnd, progress)
  const focus = smooth(BEATS.focusStart, BEATS.focusEnd, progress)

  const data = useMemo(() => {
    const seeds = new Float32Array(count * 6)
    const colors = new Float32Array(count * 3)
    for (let i = 0; i < count; i += 1) {
      const o = i * 6
      seeds[o] = (seededRandom(i + 1) - 0.5) * 22
      seeds[o + 1] = 0.4 + seededRandom(i + 20) * 7
      seeds[o + 2] = (seededRandom(i + 40) - 0.5) * 16
      seeds[o + 3] = 0.12 + seededRandom(i + 60) * 0.38
      seeds[o + 4] = 0.25 + seededRandom(i + 80) * 0.9
      seeds[o + 5] = seededRandom(i + 100) * Math.PI * 2
      const c = new THREE.Color(PALETTE[i % PALETTE.length])
      colors[i * 3] = c.r
      colors[i * 3 + 1] = c.g
      colors[i * 3 + 2] = c.b
    }
    return { seeds, colors }
  }, [])

  useFrame((state) => {
    if (!mesh.current) return
    const t = state.clock.elapsedTime
    const fade = (1 - focus * 0.25) * (1 - clear)
    const { seeds } = data

    for (let i = 0; i < count; i += 1) {
      const o = i * 6
      const drift = seeds[o + 4]
      const phase = seeds[o + 5]
      const x = seeds[o] + Math.sin(t * drift * 0.35 + phase) * 0.45
      const y = seeds[o + 1] + Math.cos(t * drift * 0.42 + phase * 1.3) * 0.35
      const z = seeds[o + 2] + Math.sin(t * drift * 0.28 + phase * 0.7) * 0.4
      const s = seeds[o + 3] * (0.7 + fade * 0.3)
      _pos.set(x, y, z)
      _quat.setFromEuler(new THREE.Euler(t * 0.05 * drift, t * 0.08 * drift, 0))
      _scl.set(s, s, s)
      _matrix.compose(_pos, _quat, _scl)
      mesh.current.setMatrixAt(i, _matrix)
    }
    mesh.current.instanceMatrix.needsUpdate = true
    mesh.current.visible = fade > 0.04
    mesh.current.material.opacity = 0.55 * fade
  })

  return (
    <instancedMesh ref={mesh} args={[undefined, undefined, count]} frustumCulled={false}>
      <sphereGeometry args={[1, 16, 16]} />
      <meshStandardMaterial
        color="#7ec8c8"
        emissive="#2a7a74"
        emissiveIntensity={0.25}
        metalness={0.2}
        roughness={0.28}
        transparent
        opacity={0.55}
        depthWrite={false}
      />
    </instancedMesh>
  )
}

/** Mid-field interactive spheres with hover glow/scale */
function InteractiveField({ progress }) {
  const layout = useMemo(() => {
    const items = []
    for (let i = 0; i < 48; i += 1) {
      items.push({
        id: i,
        base: [
          (seededRandom(i + 3) - 0.5) * 14,
          0.8 + seededRandom(i + 15) * 4.2,
          (seededRandom(i + 27) - 0.5) * 10,
        ],
        scale: 0.22 + seededRandom(i + 40) * 0.38,
        drift: 0.35 + seededRandom(i + 55) * 0.7,
        phase: seededRandom(i + 70) * Math.PI * 2,
        color: PALETTE[i % PALETTE.length],
      })
    }
    return items
  }, [])

  const clear = smooth(BEATS.clearStart, BEATS.clearEnd, progress)
  const focus = smooth(BEATS.focusStart, BEATS.focusEnd, progress)
  const fade = (1 - focus * 0.3) * (1 - clear)

  if (fade < 0.03) return null

  return (
    <group>
      {layout.map((item) => (
        <HoverSphere key={item.id} item={item} fade={fade} />
      ))}
    </group>
  )
}

function HoverSphere({ item, fade }) {
  const mesh = useRef()
  const mat = useRef()
  const hovered = useRef(false)
  const hoverAmt = useRef(0)
  const baseColor = useMemo(() => new THREE.Color(item.color), [item.color])

  useFrame((state, delta) => {
    if (!mesh.current || !mat.current) return
    const t = state.clock.elapsedTime
    const { base, drift, phase, scale } = item

    hoverAmt.current = lerp(hoverAmt.current, hovered.current ? 1 : 0, 1 - Math.exp(-delta * 10))

    const x = base[0] + Math.sin(t * drift + phase) * 0.35
    const y = base[1] + Math.cos(t * drift * 1.1 + phase) * 0.28
    const z = base[2] + Math.sin(t * drift * 0.8 + phase * 0.5) * 0.3
    mesh.current.position.set(x, y, z)

    const s = scale * (1 + hoverAmt.current * 0.55) * (0.75 + fade * 0.25)
    _objScale.setScalar(s)
    mesh.current.scale.lerp(_objScale, 1 - Math.exp(-delta * 8))

    mat.current.emissiveIntensity = 0.3 + hoverAmt.current * 1.4
    mat.current.opacity = fade * (0.75 + hoverAmt.current * 0.25)
    _color.copy(baseColor).lerp(_hoverColor, hoverAmt.current * 0.45)
    mat.current.color.copy(_color)
    mat.current.emissive.copy(_color)
  })

  return (
    <mesh
      ref={mesh}
      onPointerOver={(e) => {
        e.stopPropagation()
        hovered.current = true
        document.body.style.cursor = 'pointer'
      }}
      onPointerOut={() => {
        hovered.current = false
        document.body.style.cursor = 'auto'
      }}>
      <sphereGeometry args={[1, 28, 28]} />
      <meshPhysicalMaterial
        ref={mat}
        color={item.color}
        emissive={item.color}
        emissiveIntensity={0.3}
        metalness={0.18}
        roughness={0.2}
        clearcoat={1}
        clearcoatRoughness={0.15}
        transparent
        opacity={0.85}
      />
    </mesh>
  )
}

/** Single circular hero molecule */
function HeroSphere({ progress }) {
  const mesh = useRef()
  const mat = useRef()
  const hovered = useRef(false)
  const hoverAmt = useRef(0)

  useFrame((state, delta) => {
    if (!mesh.current || !mat.current) return
    const t = state.clock.elapsedTime
    const focus = smooth(BEATS.focusStart, BEATS.focusEnd, progress)
    const transit = smooth(BEATS.transitStart, BEATS.transitEnd, progress)
    const brand = smooth(BEATS.brandStart, BEATS.brandEnd, progress)
    hoverAmt.current = lerp(hoverAmt.current, hovered.current ? 1 : 0, 1 - Math.exp(-delta * 10))

    if (progress < BEATS.transitStart) {
      heroTarget.set(
        lerp(2.2, 0, focus) + Math.sin(t * 0.45) * 0.08 * (1 - focus),
        lerp(1.6, 2.0, focus) + Math.cos(t * 0.55) * 0.06 * (1 - focus),
        lerp(1.1, 0.15, focus),
      )
    } else if (progress < BEATS.poreOutEnd) {
      heroTarget.set(0, lerp(2.0, -2.3, transit), 0.1)
    } else {
      heroTarget.set(lerp(0, 1.55, brand), lerp(-2.3, 0.06, brand), lerp(0.1, 0.25, brand))
    }

    mesh.current.position.lerp(heroTarget, 1 - Math.exp(-delta * 5.5))

    const size =
      lerp(0.42, 0.72, focus) * lerp(1, 0.82, transit * 0.4) * lerp(1, 0.28, brand) * (1 + hoverAmt.current * 0.12)
    mesh.current.scale.setScalar(size)

    mat.current.emissiveIntensity = 0.55 + focus * 0.5 + hoverAmt.current * 0.8 + transit * 0.25
    mat.current.roughness = 0.18 - hoverAmt.current * 0.06
  })

  return (
    <mesh
      ref={mesh}
      onPointerOver={(e) => {
        e.stopPropagation()
        hovered.current = true
        document.body.style.cursor = 'pointer'
      }}
      onPointerOut={() => {
        hovered.current = false
        document.body.style.cursor = 'auto'
      }}>
      <sphereGeometry args={[1, 64, 64]} />
      <meshPhysicalMaterial
        ref={mat}
        color="#5fdad1"
        emissive="#3ecfc0"
        emissiveIntensity={0.55}
        metalness={0.25}
        roughness={0.18}
        clearcoat={1}
        clearcoatRoughness={0.08}
      />
    </mesh>
  )
}

/** Flat horizontal membrane with circular aperture */
function Nanopore({ progress }) {
  const group = useRef()
  const sheet = useRef()
  const rim = useRef()
  const glow = useRef()

  const visible =
    smooth(BEATS.poreInStart, BEATS.poreInEnd, progress) * (1 - smooth(BEATS.poreOutStart, BEATS.poreOutEnd, progress))

  const nodes = useMemo(() => {
    const list = []
    for (let i = 0; i < 64; i += 1) {
      const a = (i / 64) * Math.PI * 2 + seededRandom(i) * 0.15
      const r = 1.3 + seededRandom(i + 3) * 3.6
      list.push([Math.cos(a) * r, 0.02, Math.sin(a) * r])
    }
    for (let i = 0; i < 28; i += 1) {
      const x = (seededRandom(i + 50) - 0.5) * 9
      const z = (seededRandom(i + 80) - 0.5) * 9
      if (Math.hypot(x, z) < 1.2) continue
      list.push([x, 0.015, z])
    }
    return list
  }, [])

  useFrame((state, delta) => {
    if (!group.current) return
    const pulse = 1 + Math.sin(state.clock.elapsedTime * 1.4) * 0.01
    poreScale.set(pulse, 1, pulse)
    group.current.scale.lerp(poreScale, 1 - Math.exp(-delta * 4))
    group.current.visible = visible > 0.01
    if (sheet.current) sheet.current.opacity = visible * 0.78
    if (rim.current) rim.current.opacity = visible
    if (glow.current) glow.current.opacity = visible * 0.4
  })

  return (
    <group ref={group}>
      <mesh rotation={[-Math.PI / 2, 0, 0]}>
        <ringGeometry args={[1.05, 5.8, 128]} />
        <meshStandardMaterial
          ref={sheet}
          color="#6eb8b0"
          emissive="#1f5c58"
          emissiveIntensity={0.22}
          metalness={0.28}
          roughness={0.4}
          transparent
          side={THREE.DoubleSide}
          depthWrite={false}
        />
      </mesh>
      <mesh rotation={[-Math.PI / 2, 0, 0]} position={[0, 0.012, 0]}>
        <ringGeometry args={[1.02, 1.2, 96]} />
        <meshStandardMaterial
          ref={rim}
          color="#5fdad1"
          emissive="#3ecfc0"
          emissiveIntensity={1.5}
          metalness={0.35}
          roughness={0.2}
          transparent
          side={THREE.DoubleSide}
        />
      </mesh>
      <mesh rotation={[-Math.PI / 2, 0, 0]} position={[0, -0.01, 0]}>
        <ringGeometry args={[1.15, 1.6, 96]} />
        <meshBasicMaterial ref={glow} color="#7ef0e4" transparent side={THREE.DoubleSide} depthWrite={false} />
      </mesh>
      {nodes.map((pos, i) => (
        <mesh key={i} position={pos}>
          <sphereGeometry args={[0.035 + seededRandom(i) * 0.02, 8, 8]} />
          <meshStandardMaterial color="#9fd4ce" emissive="#3a8a84" emissiveIntensity={0.18} roughness={0.4} />
        </mesh>
      ))}
    </group>
  )
}
